-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- ============================================================
-- Fix RLS Recursion and Ambiguity
-- ============================================================

-- 1. Drop problematic policies on lms.users
DROP POLICY IF EXISTS "users: admin read all" ON lms.users;
DROP POLICY IF EXISTS "users: admin update" ON lms.users;

-- 2. Create a secure function to check admin status without recursion
-- This function uses SECURITY DEFINER to bypass RLS checks on the users table
CREATE OR REPLACE FUNCTION lms.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM lms.users
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. Re-create policies using the helper function
CREATE POLICY "users: admin read all" ON lms.users
  FOR SELECT USING (lms.is_admin());

CREATE POLICY "users: admin update" ON lms.users
  FOR UPDATE
  USING (lms.is_admin())
  WITH CHECK (lms.is_admin());

-- 4. Fix other tables that might have similar recursive patterns
DROP POLICY IF EXISTS "modules: admin all" ON lms.modules;
CREATE POLICY "modules: admin all" ON lms.modules
  USING (lms.is_admin());

DROP POLICY IF EXISTS "progress: admin all" ON lms.learner_progress;
CREATE POLICY "progress: admin all" ON lms.learner_progress
  USING (lms.is_admin());

DROP POLICY IF EXISTS "activity_logs: admin all" ON lms.activity_logs;
CREATE POLICY "activity_logs: admin all" ON lms.activity_logs
  USING (lms.is_admin());

DROP POLICY IF EXISTS "storage: admin write" ON storage.objects;
CREATE POLICY "storage: admin write" ON storage.objects
  FOR INSERT
  WITH CHECK (
    bucket_id = 'study-notes' AND lms.is_admin()
  );
